export const EXPERT_AGENT_COUNT = 215;

const normalize = (value: string) =>
  value.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

/** Palavras comuns demais para indicar uma especialidade. */
const GENERIC_TOKENS = new Set([
  'bem', 'tudo', 'como', 'para', 'com', 'que', 'uma', 'uns', 'das', 'dos', 'por', 'mais', 'muito',
  'site', 'sites', 'app', 'apps', 'aplicativo', 'aplicativos', 'sistema', 'quero', 'preciso', 'crie',
  'criar', 'fazer', 'faca', 'meu', 'minha', 'pode', 'gostaria', 'favor', 'bom', 'boa', 'dia', 'tarde',
  'noite', 'ola', 'oi', 'novo', 'nova', 'sobre', 'tenho', 'ajuda', 'ajudar',
]);
const MAX_AGENTS_PER_TOKEN = 8;

function keywordMatches(token: string, keyword: string): boolean {
  if (keyword.length <= 3) return token === keyword;
  return token.startsWith(keyword) || (token.length >= 5 && keyword.startsWith(token));
}

/** Escolhe os especialistas mais relevantes; devolve [] para conversa simples. */
export function routeExpertAgents(prompt: string, limit = 4): ExpertAgentProfile[] {
  if (!prompt || prompt.trim().length < 12) return [];
  const promptTokens = Array.from(new Set(normalize(prompt).split(/[^a-z0-9]+/).filter(token => token.length >= 2)))
    .filter(token => !GENERIC_TOKENS.has(token));
  const scores = new Map<number, number>();
  for (const token of promptTokens) {
    const matched: number[] = [];
    EXPERT_AGENTS.forEach((agent, index) => {
      if (agent.keywords.some(keyword => keywordMatches(token, keyword))) matched.push(index);
    });
    if (matched.length === 0 || matched.length > MAX_AGENTS_PER_TOKEN) continue;
    for (const index of matched) {
      const agent = EXPERT_AGENTS[index];
      const named = agent.id.split('-').some(part => part.length >= 4 && (token.startsWith(part) || part.startsWith(token)));
      scores.set(index, (scores.get(index) || 0) + 1 / matched.length + (named ? 0.5 : 0));
    }
  }
  return Array.from(scores.entries())
    .sort((a, b) => b[1] - a[1] || a[0] - b[0])
    .slice(0, Math.max(0, limit))
    .map(([index]) => EXPERT_AGENTS[index]);
}

export function describeExpertAgent(agent: ExpertAgentProfile): string {
  return [
    `Especialista ${agent.name} (${agent.categoryLabel}): ${agent.mission}`,
    `Metodo: ${agent.method.join(' ')}`,
    `Aceite: ${agent.acceptance.join(' ')}`,
  ].join('\n');
}

export function expertTeamPolicy(prompt: string, limit = 4): string {
  const agents = routeExpertAgents(prompt, limit);
  if (agents.length === 0) return '';
  return [
    'ESPECIALISTAS ACIONADOS PARA ESTE PEDIDO: aplique estas perspectivas no modelo desta execucao.',
    'Nao sao chamadas independentes: nao alegue deliberacao, ferramenta ou teste que nao ocorreu.',
    ...agents.map(describeExpertAgent),
  ].join('\n\n');
}
